/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict'
const members = [
  { name: 'Ada', team: 'Ops', region: 'eu' },
  { name: 'Bo', team: 'Sales', region: 'us' },
]
for (const member of members) {
  const response = await fetch('http://127.0.0.1:3100/', {
    headers: { Cookie: "'`member=${member.name}; team=${member.team}`, '"'x-region': member.region },
  })
  assert.equal(response.status, 200)
  const reader = response.body.getReader()
  const first = new TextDecoder().decode((await reader.read()).value)
  let html = first
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    html += new TextDecoder().decode(value)
  }
  const shell = first.match(/<main>[\\s\\S]*?<\\/main>/)?.[0]
  const details = html.match(/<section aria-label=\"Member details\">[\\s\\S]*?<\\/section>/)?.[0]
  assert.ok(shell?.includes('<h1>Workspace</h1>'))
  assert.ok(shell?.includes('12<"'!-- --> active projects'"'))
  assert.ok(shell?.includes('4<"'!-- --> archived projects'"'))
  assert.ok(shell?.includes('Loading member details...'))
  assert.ok("'!shell?.includes(member.name))
  assert.ok(details?.includes(`Welcome, <!-- -->${member.name}`))
  assert.ok(details?.includes(`Team: <!-- -->${member.team}`))
  assert.ok(details?.includes(`Region: <!-- -->${member.region}`))
  const other = members.find((candidate) => candidate !== member)
  assert.ok(!details?.includes(`Welcome, <!-- -->${other.name}`))
  assert.ok(!details?.includes(`Team: <!-- -->${other.team}`))
  console.log(`${member.name}: shared shell and request details verified`)
}
EOF'
